<h1>Mach&ndash;Zehnder interferometer</h1>

<div class="flow-container">

  <div class="figure-box">
    <div class="placeholder">
      <svg class="schematic-svg" viewBox="0 0 600 340">
        <!-- Beam splitters (squares with diagonal) -->
        <!-- top-left -->
        <rect x="60" y="30" width="60" height="60" fill="none" stroke="black"/>
        <line x1="60" y1="90" x2="120" y2="30" stroke="black"/>
